using Microsoft.EntityFrameworkCore;
using Microsoft.Data.SqlClient;
using PhoneStore.Infrastructure.Data;
internal sealed partial class QaSuite
{
    async Task Database(){
        await Check("DB-001","Constraint vật lý chặn dữ liệu lỗi","CHECK/PK/FK từ chối và rollback",async()=>{await using var db=Open();var v=await db.Stock.FirstAsync();
            foreach(var command in new FormattableString[]{ $"UPDATE TON_KHO SET Reserved=-1 WHERE VariantId={v.VariantId}", $"INSERT INTO TON_KHO(VariantId,OnHand,Reserved) VALUES({v.VariantId},0,0)", $"INSERT INTO TON_KHO(VariantId,OnHand,Reserved) VALUES({long.MaxValue},0,0)" }){await using var tx=await db.Database.BeginTransactionAsync();var rejected=false;try{await db.Database.ExecuteSqlInterpolatedAsync(command);}catch(SqlException e)when(e.Number is 547 or 2627 or 2601){rejected=true;}finally{await tx.RollbackAsync();}Assert(rejected,"SQL constraint accepted invalid record");}
        },kind:"SQL trực tiếp trên DB QA");
        await Check("DB-002","Toàn vẹn constraint hiện tại","DBCC CHECKCONSTRAINTS không có dòng lỗi",async()=>{await using var db=Open();await db.Database.OpenConnectionAsync();using var command=db.Database.GetDbConnection().CreateCommand();command.CommandText="DBCC CHECKCONSTRAINTS WITH ALL_CONSTRAINTS";await using var reader=await command.ExecuteReaderAsync();Assert(!await reader.ReadAsync());},kind:"SQL runtime");
        await Check("DB-004","Tiền decimal(18,2)","Tất cả thuộc tính tiền EF khớp precision/scale",async()=>{await using var db=Open();var cols=db.Model.GetEntityTypes().SelectMany(x=>x.GetProperties()).Where(x=>x.ClrType==typeof(decimal)).ToList();Assert(cols.Count>=6&&cols.All(x=>x.GetPrecision()==18&&x.GetScale()==2));},kind:"Metadata EF + schema đã tạo");
        await Check("DB-008","Không cascade xóa lịch sử","Không có FK cascade; SQL chặn xóa sản phẩm tham chiếu",async()=>{await using var db=Open();Assert(db.Model.GetEntityTypes().SelectMany(x=>x.GetForeignKeys()).All(x=>x.DeleteBehavior==DeleteBehavior.NoAction));var p=await db.Products.FirstAsync();await using var tx=await db.Database.BeginTransactionAsync();bool rejected=false;try{await db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM SAN_PHAM WHERE Id={p.Id}");}catch(SqlException e)when(e.Number==547){rejected=true;}finally{await tx.RollbackAsync();}Assert(rejected);});
        await Check("DB-015","Đối chiếu toàn bộ tổng chứng từ","Tổng đơn/phiếu khớp dòng, COD không chênh",async()=>{await using var db=Open();var orders=await db.Orders.Include(x=>x.Lines).Include(x=>x.Payment).ToListAsync();Assert(orders.All(x=>x.Total==x.Lines.Sum(l=>l.Price*l.Quantity)));Assert(orders.All(x=>x.Payment.Status=="DA_THU"?x.Payment.Amount==x.Total:x.Payment.Amount==0));var purchases=await db.Purchases.Include(x=>x.Lines).ToListAsync();Assert(purchases.All(x=>x.Total==x.Lines.Sum(l=>l.Cost*l.Quantity)));});
        await Check("DB-016","Đối chiếu giữ theo trạng thái đơn và nhật ký kho","Mọi biến thể có số dư và held đúng",async()=>{await using var db=Open();var stocks=await db.Stock.ToListAsync();var moves=await db.Movements.ToListAsync();var open=await db.OrderLines.Where(x=>x.Order.Status=="CHO_XAC_NHAN"||x.Order.Status=="DA_XAC_NHAN").ToListAsync();foreach(var row in stocks){Assert(row.OnHand>=row.Reserved&&row.Reserved>=0);Assert(row.OnHand==moves.Where(x=>x.VariantId==row.VariantId).Sum(x=>x.DeltaOnHand));Assert(row.Reserved==moves.Where(x=>x.VariantId==row.VariantId).Sum(x=>x.DeltaReserved));Assert(row.Reserved==open.Where(x=>x.VariantId==row.VariantId).Sum(x=>x.Quantity));}});
        await Check("DB-012","Index truy vấn chính tồn tại","Có index customer/date, status/date, SKU và journal",async()=>{await using var db=Open();await db.Database.OpenConnectionAsync();using var command=db.Database.GetDbConnection().CreateCommand();command.CommandText="SELECT COUNT(*) FROM sys.indexes WHERE name IN ('IX_DON_HANG_CustomerId_CreatedAt','IX_DON_HANG_Status_CreatedAt','IX_BIEN_THE_Sku','IX_NHAT_KY_KHO_VariantId_At')";Assert(Convert.ToInt32(await command.ExecuteScalarAsync())==4);},kind:"Schema runtime; chưa benchmark execution plan");
    }
}
